/** Public job types, payload validation, and row-to-JSON mapping shared by the server and worker. */

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The JSON shape returned by every endpoint that describes a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** A row of the `jobs` table, exactly as SQLite returns it. */
export interface JobRow {
  seq: number;
  id: string;
  idempotency_key: string | null;
  input: string;
  steps: number;
  fail_attempts: number;
  status: JobStatus;
  attempts: number;
  completed_steps: number;
  resume: number;
  output: string | null;
  error: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** Validated submission, with defaults applied. */
export interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

export const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

export const isObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

function isIntegerIn(v: unknown, min: number, max: number): boolean {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

/** Returns one error per offending field of a parsed request body. Does not apply defaults. */
export function checkFields(body: Record<string, unknown>): FieldError[] {
  const errors: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) errors.push({ field: key, message: 'Unknown field.' });
  }

  const input = body.input;
  if (input === undefined) {
    errors.push({ field: 'input', message: 'Required.' });
  } else if (typeof input !== 'string') {
    errors.push({ field: 'input', message: 'Must be a string.' });
  } else if (input.length < 1 || input.length > 1000) {
    errors.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
  } else if (input.trim() === '') {
    errors.push({ field: 'input', message: 'Must not be blank.' });
  }

  if (body.steps !== undefined && !isIntegerIn(body.steps, 1, 20)) {
    errors.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
  }
  if (body.failAttempts !== undefined && !isIntegerIn(body.failAttempts, 0, 5)) {
    errors.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
  }
  return errors;
}

/** Builds the payload from a body that passed checkFields, applying defaults to absent fields only. */
export function toPayload(body: Record<string, unknown>): Payload {
  return {
    input: body.input as string,
    steps: body.steps === undefined ? 5 : (body.steps as number),
    failAttempts: body.failAttempts === undefined ? 0 : (body.failAttempts as number),
  };
}

export function samePayload(a: Payload, b: Payload): boolean {
  return a.input === b.input && a.steps === b.steps && a.failAttempts === b.failAttempts;
}

export function rowToJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed_steps, total: row.steps },
    result: row.status === 'completed' ? { output: row.output ?? '' } : null,
    error: row.status === 'failed' ? (row.error ?? '') : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

