import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';
import { samePayload, type JobRow, type Payload } from './jobs.ts';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  idempotency_key TEXT UNIQUE,
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
  attempts INTEGER NOT NULL DEFAULT 0,
  completed_steps INTEGER NOT NULL DEFAULT 0,
  resume INTEGER NOT NULL DEFAULT 0,
  output TEXT,
  error TEXT,
  available_at INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, available_at, seq);
CREATE TABLE IF NOT EXISTS heartbeat (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  last_seen INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes and ensures the schema exists. */
export function openDatabase(path: string = process.env.DATABASE_PATH || 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}

/**
 * Runs `fn` inside a write transaction. Keep `fn` synchronous and short: no timers, no awaits,
 * no HTTP reads while the transaction is open.
 */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // The original error is the one worth reporting.
    }
    throw e;
  }
  db.exec('COMMIT');
  return result;
}

function getRowById(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
}

export function getJob(db: DatabaseSync, id: string): JobRow | undefined {
  return getRowById(db, id);
}

export function listJobs(db: DatabaseSync): JobRow[] {
  return db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
}

export type Submission =
  | { kind: 'created'; row: JobRow }
  | { kind: 'replayed'; row: JobRow }
  | { kind: 'conflict' };

/** Creates a queued job, or replays/conflicts with an existing job that used the same idempotency key. */
export function submitJob(db: DatabaseSync, payload: Payload, key: string | null): Submission {
  return transaction(db, (): Submission => {
    if (key !== null) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as JobRow | undefined;
      if (existing) {
        const same = samePayload(payload, {
          input: existing.input,
          steps: existing.steps,
          failAttempts: existing.fail_attempts,
        });
        return same ? { kind: 'replayed', row: existing } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, idempotency_key, input, steps, fail_attempts, status, attempts,
                         completed_steps, resume, available_at, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, 'queued', 0, 0, 0, 0, ?, ?)`,
    ).run(id, key, payload.input, payload.steps, payload.failAttempts, now, now);
    const row = getRowById(db, id);
    if (!row) throw new Error('inserted job not found');
    return { kind: 'created', row };
  });
}

// ---- Worker-side persistence -------------------------------------------------------------

/** Moves jobs interrupted mid-attempt back to the queue, to be replayed as the same attempt. */
export function recoverInterrupted(db: DatabaseSync, now: number): void {
  transaction(db, () => {
    db.prepare(
      `UPDATE jobs SET status = 'queued', resume = 1, completed_steps = 0, available_at = 0, updated_at = ?
       WHERE status = 'running'`,
    ).run(new Date(now).toISOString());
  });
}

/** Claims the oldest eligible queued job, or returns undefined when none is ready. */
export function claimNext(db: DatabaseSync, now: number): JobRow | undefined {
  return transaction(db, () => {
    const next = db
      .prepare(
        `SELECT seq FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq ASC LIMIT 1`,
      )
      .get(now) as { seq: number } | undefined;
    if (!next) return undefined;
    db.prepare(
      `UPDATE jobs
       SET status = 'running',
           attempts = attempts + CASE WHEN resume = 1 THEN 0 ELSE 1 END,
           resume = 0,
           completed_steps = 0,
           output = NULL,
           error = NULL,
           updated_at = ?
       WHERE seq = ?`,
    ).run(new Date(now).toISOString(), next.seq);
    return db.prepare('SELECT * FROM jobs WHERE seq = ?').get(next.seq) as unknown as JobRow;
  });
}

export function recordProgress(db: DatabaseSync, id: string, completed: number, now: number): void {
  transaction(db, () => {
    db.prepare(`UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE id = ? AND status = 'running'`).run(
      completed,
      new Date(now).toISOString(),
      id,
    );
  });
}

/** Records a simulated transient failure: requeue with a delay, or fail permanently on the last attempt. */
export function recordFailedAttempt(
  db: DatabaseSync,
  id: string,
  attempt: number,
  maxAttempts: number,
  retryDelayMs: number,
  now: number,
): 'retry' | 'failed' {
  return transaction(db, () => {
    const ts = new Date(now).toISOString();
    if (attempt >= maxAttempts) {
      db.prepare(
        `UPDATE jobs SET status = 'failed', error = 'transient failure', output = NULL,
                         completed_steps = 0, resume = 0, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ).run(ts, id);
      return 'failed';
    }
    db.prepare(
      `UPDATE jobs SET status = 'queued', completed_steps = 0, output = NULL, error = NULL,
                       resume = 0, available_at = ?, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ).run(now + retryDelayMs, ts, id);
    return 'retry';
  });
}

export function recordCompleted(db: DatabaseSync, id: string, output: string, now: number): void {
  transaction(db, () => {
    db.prepare(
      `UPDATE jobs SET status = 'completed', completed_steps = steps, output = ?, error = NULL, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ).run(output, new Date(now).toISOString(), id);
  });
}

// ---- Heartbeat ----------------------------------------------------------------------------

export function writeHeartbeat(db: DatabaseSync, now: number): void {
  db.prepare(
    `INSERT INTO heartbeat (id, last_seen) VALUES (1, ?)
     ON CONFLICT(id) DO UPDATE SET last_seen = excluded.last_seen`,
  ).run(now);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('DELETE FROM heartbeat WHERE id = 1').run();
}

export function readHeartbeat(db: DatabaseSync): number | undefined {
  const row = db.prepare('SELECT last_seen FROM heartbeat WHERE id = 1').get() as
    | { last_seen: number }
    | undefined;
  return row?.last_seen;
}

