import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { getJob, listJobs, openDatabase, readHeartbeat, submitJob } from './db.ts';
import { checkFields, isObject, KEY_PATTERN, rowToJob, toPayload, type FieldError } from './jobs.ts';

const HEARTBEAT_FRESH_MS = 3000;
const MAX_BODY_BYTES = 1024 * 1024;
const SHUTDOWN_GRACE_MS = 3000;
const SHUTDOWN_HARD_MS = 5000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error });
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this route.', undefined);
  res.setHeader('allow', allow);
}

function mediaType(header: string | undefined): string | undefined {
  return header?.split(';')[0]?.trim().toLowerCase();
}

/** Reads the whole body. Returns null when it exceeds the size limit. */
async function readBody(req: IncomingMessage): Promise<Buffer | null> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const buf = chunk as Buffer;
    size += buf.length;
    if (size > MAX_BODY_BYTES) return null;
    chunks.push(buf);
  }
  return Buffer.concat(chunks);
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const errors: FieldError[] = [];

  if (mediaType(req.headers['content-type']) !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json.' });
  }

  const raw = await readBody(req);
  let body: Record<string, unknown> | undefined;
  if (raw === null) {
    errors.push({ field: 'body', message: `Request body must be at most ${MAX_BODY_BYTES} bytes.` });
    res.setHeader('connection', 'close');
  } else {
    try {
      const parsed: unknown = JSON.parse(raw.toString('utf8'));
      if (isObject(parsed)) body = parsed;
      else errors.push({ field: 'body', message: 'Request body must be a JSON object.' });
    } catch {
      errors.push({ field: 'body', message: 'Request body must be valid JSON.' });
    }
  }

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !KEY_PATTERN.test(key)) {
    errors.push({
      field: 'Idempotency-Key',
      message: 'Must be 1 to 128 characters: letters, digits, underscores, or hyphens.',
    });
  }

  if (body) errors.push(...checkFields(body));
  if (errors.length > 0) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
    return;
  }

  const submission = submitJob(db, toPayload(body ?? {}), key ?? null);
  if (submission.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, submission.kind === 'created' ? 201 : 200, rowToJob(submission.row));
}

function safeDecode(segment: string): string | undefined {
  try {
    return decodeURIComponent(segment);
  } catch {
    return undefined;
  }
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const isGet = method === 'GET' || method === 'HEAD';
  const path = (req.url ?? '/').split(/[?#]/, 1)[0] ?? '/';

  if (path === '/') {
    if (!isGet) return methodNotAllowed(res, 'GET, HEAD');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (path === '/health') {
    if (!isGet) return methodNotAllowed(res, 'GET, HEAD');
    const lastSeen = readHeartbeat(db);
    const up = lastSeen !== undefined && Date.now() - lastSeen <= HEARTBEAT_FRESH_MS;
    sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
    return;
  }

  if (path === '/api/jobs') {
    if (isGet) {
      sendJson(res, 200, { jobs: listJobs(db).map(rowToJob) });
      return;
    }
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, 'GET, HEAD, POST');
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (match) {
    if (!isGet) return methodNotAllowed(res, 'GET, HEAD');
    const id = safeDecode(match[1] ?? '');
    const row = id === undefined ? undefined : getJob(db, id);
    if (!row) {
      sendError(res, 404, 'not_found', 'Job not found.');
      return;
    }
    sendJson(res, 200, rowToJob(row));
    return;
  }

  sendError(res, 404, 'not_found', 'Route not found.');
}

const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    // Log for operators only; never send SQL or stack details to the client.
    console.error('request failed:', err instanceof Error ? err.message : String(err));
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

let shuttingDown = false;
function shutdown(signal: string): void {
