import { setInterval as every, setTimeout as sleep } from 'node:timers/promises';
import {
  claimNext,
  clearHeartbeat,
  openDatabase,
  recordCompleted,
  recordFailedAttempt,
  recordProgress,
  recoverInterrupted,
  writeHeartbeat,
} from './db.ts';
import type { JobRow } from './jobs.ts';

const STEP_MS = 100;
const POLL_MS = 100;
const HEARTBEAT_MS = 500;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function beat(): void {
  try {
    writeHeartbeat(db, Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err instanceof Error ? err.message : String(err));
  }
}

/** Processes one attempt step by step. Returns early (leaving the job running) if asked to stop. */
async function runAttempt(job: JobRow): Promise<void> {
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return; // Left `running`; recovery replays this attempt on the next start.

    if (step === 1 && job.attempts <= job.fail_attempts) {
      const outcome = recordFailedAttempt(db, job.id, job.attempts, MAX_ATTEMPTS, RETRY_DELAY_MS, Date.now());
      console.log(`job ${job.id} attempt ${job.attempts} failed (${outcome})`);
      return;
    }

    if (step < job.steps) {
      recordProgress(db, job.id, step, Date.now());
    } else {
      recordCompleted(db, job.id, job.input.toUpperCase(), Date.now());
      console.log(`job ${job.id} completed`);
    }
  }
}

async function main(): Promise<void> {
  recoverInterrupted(db, Date.now());
  beat();
  const heartbeat = setInterval(beat, HEARTBEAT_MS);
  console.log('worker started');

  while (!stopping) {
    const job = claimNext(db, Date.now());
    if (!job) {
      await sleep(POLL_MS);
      continue;
    }
    await runAttempt(job);
  }

  clearInterval(heartbeat);
  clearHeartbeat(db);
  db.close();
  console.log('worker stopped');
  process.exit(0);
}

void every; // Kept import-free of unused helpers; timers come from node:timers/promises above.
main().catch((err: unknown) => {
  console.error('worker failed:', err instanceof Error ? err.message : String(err));
  process.exit(1);
});

