cat > "$TMPDIR/probe/p2.mjs" <<'EOF'
import { spawn } from 'node:child_process';
import { mkdtempSync, openSync } from 'node:fs';
import { join } from 'node:path';
const ROOT = process.argv[2];
const dir = mkdtempSync(join(process.env.TMPDIR, 'jt2-'));
const env = { ...process.env, PORT: '4818', DATABASE_PATH: join(dir, 'a', 'b.db') };
const base = 'http://localhost:4818';
const start = (s) => spawn('node', ['--disable-warning=ExperimentalWarning', join(ROOT, 'dist', s)], { env, stdio: ['ignore', openSync(join(dir, s + '.log'), 'a'), openSync(join(dir, s + '.log'), 'a')] });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const get = async (p) => (await fetch(base + p)).json();
const post = async (b) => (await fetch(base + '/api/jobs', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(b) })).json();
const server = start('server.js'); let worker = start('worker.js');
await sleep(1500);
const j = await post({ input: 'progress test', steps: 20 });
const seen = new Set(); let maxC = 0;
for (let i = 0; i < 40; i++) { const s = await get(`/api/jobs/${j.id}`); seen.add(s.status + ':' + s.progress.completed); await sleep(100); }
console.log('observed', [...seen].slice(0, 12).join(' '), '...', seen.size, 'distinct');
// kill mid-run
const k = await post({ input: 'kill me', steps: 20, failAttempts: 0 });
while ((await get(`/api/jobs/${k.id}`)).status !== 'running') await sleep(50);
await sleep(500);
const mid = await get(`/api/jobs/${k.id}`);
worker.kill('SIGKILL'); await sleep(300);
worker = start('worker.js');
const t0 = Date.now(); let fin;
for (;;) { fin = await get(`/api/jobs/${k.id}`); if (fin.status === 'completed' || fin.status === 'failed' || Date.now() - t0 > 15000) break; await sleep(100); }
console.log('mid-run', JSON.stringify(mid.progress), mid.status, '-> after restart', fin.status, JSON.stringify(fin.progress), 'attempts', fin.attempts, 'output', fin.result?.output, 'in', Date.now() - t0, 'ms');
// interrupted during attempt 3 (failAttempts 3 -> should fail at attempt 3 after recovery)
const r = await post({ input: 'third', steps: 20, failAttempts: 3 });
const att = { t: null };
while (true) { const s = await get(`/api/jobs/${r.id}`); if (s.attempts === 3 && s.status === 'running') break; if (s.status === 'failed') break; await sleep(50); }
worker.kill('SIGKILL'); await sleep(300);
worker = start('worker.js');
const t1 = Date.now(); let f3;
for (;;) { f3 = await get(`/api/jobs/${r.id}`); if (f3.status === 'completed' || f3.status === 'failed' || Date.now() - t1 > 20000) break; await sleep(100); }
console.log('attempt3 interrupted ->', f3.status, 'attempts', f3.attempts, f3.error);
const wExit = new Promise((res) => worker.on('exit', res)); const sExit = new Promise((res) => server.on('exit', res));
worker.kill('SIGTERM'); server.kill('SIGTERM');
console.log('exit codes', await wExit, await sExit);
EOF
cd <workspace> && timeout 200 node "$TMPDIR/probe/p2.mjs" "$PWD" 2>&1 | tail -20
